python3 -c '
def get_notes_and_tonic(tonic):
    # Normalize accidental
    acc = ""
    if len(tonic) > 1:
        if tonic[1] in ("b", "B", "♭"):
            acc = "b"
        elif tonic[1] in ("#", "♯"):
            acc = "#"
        else:
            acc = tonic[1]

    # If explicit flat accidental -> FLATS
    # If explicit sharp accidental -> SHARPS
    # If natural -> check if in {"F", "d", "g", "c", "f"}
    if acc == "b":
        use_flats = True
    elif acc == "#":
        use_flats = False
    else:
        use_flats = tonic in {"F", "d", "g", "c", "f"}

    tonic_name = tonic[0].upper() + acc
    return use_flats, tonic_name

SHARPS = ("A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#")
FLATS = ("A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab")

test_cases = [
    # Table cases
    "C", "a",
    "G", "D", "A", "E", "B", "F#",
    "e", "b", "f#", "c#", "g#", "d#",
    "F", "Bb", "Eb", "Ab", "Db", "Gb",
    "d", "g", "c", "f", "bb", "eb",
    # Edge cases
    "ab", "db", "gb", "B♭", "E♭", "F♯", "G#"
]

for t in test_cases:
    use_flats, name = get_notes_and_tonic(t)
    pool = FLATS if use_flats else SHARPS
    assert name in pool, f"Failed for {t}: {name} not in {pool}"
print("All table and edge cases passed cleanly!")
'
